import { useEffect, useState } from 'react';
import { audio as audioService } from './audio';
import { parseBreathSoundRef } from './breathSounds';

// One preview player for the whole app, so starting a preview stops any other.
// The caller passes the volume background music has during a session.
// A sound that follows the breath is generated by the audio service instead:
// a few sample breaths, at the music level.

let audio = null;
let playingRef = null; // the sound reference currently previewing, or null
const listeners = new Set();

const setPlaying = (ref) => {
  playingRef = ref;
  listeners.forEach((listener) => listener(ref));
};

export const stopPreview = () => {
  audioService.stopBreathPreview();
  if (audio) {
    audio.pause();
    audio.removeAttribute('src');
    audio.load();
  }
  setPlaying(null);
};

export const playPreview = async (ref, url, volume = 1) => {
  stopPreview();
  const breathSound = parseBreathSoundRef(ref);
  if (breathSound) {
    setPlaying(ref);
    audioService.previewBreathSound(breathSound, () => {
      if (playingRef === ref) setPlaying(null);
    });
    return;
  }
  if (!url) return;
  audio ??= new Audio();
  audio.src = url;
  setPreviewVolume(volume);
  audio.onended = stopPreview;
  setPlaying(ref);
  try {
    await audio.play();
  } catch (e) {
    console.warn('Preview failed to play:', e);
    stopPreview();
  }
};

// Follows the music level slider while a preview plays
export const setPreviewVolume = (volume) => {
  if (audio) audio.volume = Math.min(1, Math.max(0, volume));
};

// The sound reference currently previewing (re-renders when it changes)
export const usePreviewPlaying = () => {
  const [playing, setPlayingState] = useState(playingRef);
  useEffect(() => {
    listeners.add(setPlayingState);
    return () => listeners.delete(setPlayingState);
  }, []);
  return playing;
};
